1	import { supabase } from '$lib/supabaseClient';
2	import type { ReceiptInsert, ReceiptRow } from '$lib/models/Receipt';
3	import { withRetry } from '$lib/utils/retry';
4	import type { ReceiptExtract } from '$lib/utils/sanitize';
5	import { isSuspiciousDate } from '$lib/utils/dateValidation';
6	import { resolveOcrReceiptDate } from '$lib/utils/receiptDateCorrection';
7	import { resizeImage } from '$lib/utils/imageResize';
8	import { getSignedReceiptUrl } from '$lib/utils/signedUrl';
9	import { sanitizeFilename } from '$lib/utils/sanitizeFilename';
10	
11	const IMAGE_TYPES = ['image/jpeg', 'image/png', 'image/heic'];
12	const PDF_TYPE = 'application/pdf';
13	const MAX_IMAGE_MB = 5;
14	const MAX_PDF_MB = 10;
15	
16	export class ReceiptService {
17		static #instance: ReceiptService | null = null;
18		static get(): ReceiptService {
19			return (this.#instance ??= new ReceiptService());
20		}
21	
22		/**
23		 * Call the server-side OCR API to extract receipt data
24		 */
25		private async extractOcrData(fileUrl: string, mimeType: string): Promise<ReceiptExtract | null> {
26			try {
27				const response = await fetch('/api/ocr/extract', {
28					method: 'POST',
29					headers: {
30						'Content-Type': 'application/json'
31					},
32					body: JSON.stringify({ fileUrl, mimeType })
33				});
34	
35				if (!response.ok) {
36					const errorText = await response.text();
37					throw new Error(`OCR API error: ${response.status} - ${errorText}`);
38				}
39	
40				const result = await response.json();
41				return result.data;
42			} catch (e) {
43				console.error('OCR extraction failed:', e);
44				return null;
45			}
46		}
47	
48		async list(
49			sort: 'transaction_date' | 'merchant_name' | 'total_amount' = 'transaction_date',
50			direction: 'asc' | 'desc' = 'desc'
51		) {
52			return withRetry(async () => {
53				const user = (await supabase.auth.getUser()).data.user;
54				if (!user) throw new Error('Not authenticated');
55	
56				console.log('[ReceiptService] Fetching receipts for user:', user.id);
57	
58				// Check family memberships for debugging
59				const { data: familyMemberships, error: fmError } = await supabase
60					.from('family_members')
61					.select('*')
62					.eq('user_id', user.id);
63				console.log('[ReceiptService] Family memberships:', familyMemberships, fmError);
64	
65				// Don't filter by user_id - let RLS policies handle access based on family membership
66				// This allows family members to see each other's receipts
67				const { data, error } = await supabase
68					.from('receipts')
69					.select('*')
70					.order(sort, { ascending: direction === 'asc' });
71				if (error) throw error;
72	
73				console.log('[ReceiptService] Fetched receipts:', {
74					count: data.length,
75					sample: data[0]
76						? {
77								id: data[0].id,
78								merchant_name: data[0].merchant_name,
79								family_id: data[0].family_id,
80								user_id: data[0].user_id
81							}
82						: 'none'
83				});
84	
85				return data as ReceiptRow[];
86			});
87		}
88	
89		/** Fields that are safe to send in an update — matches ReceiptInsert keys */
90		static readonly #EDITABLE_FIELDS: ReadonlySet<string> = new Set([
91			'receipt_image_path',
92			'transaction_date',
93			'total_amount',
94			'tax',
95			'merchant_name',
96			'credit_card_name',
97			'credit_card_last_4',
98			'currency',
99			'exchange_rate_to_cad',
100			'matched_transaction_id',
101			'suspicious_date',
102			'split_group_id'
103		]);
104	
105		async update(id: string, patch: ReceiptInsert) {
106			return withRetry(async () => {
107				// Strip non-editable fields (id, user_id, created_at, etc.) to prevent
108				// Supabase 400 errors from invalid values being sent in the update.
109				const safePatch: ReceiptInsert = {};
110				for (const key of Object.keys(patch)) {
111					if (ReceiptService.#EDITABLE_FIELDS.has(key)) {
112						(safePatch as any)[key] = (patch as any)[key];
113					}
114				}
115	
116				// #{#dtv1b} #{#dtv2d} Saving a receipt through the edit modal clears the
117				// suspicious-date flag. The modal always sends transaction_date, so a save
118				// (date corrected or left as-is) is treated as the user's review/confirmation
119				// of the date — there is no separate "confirm date" action. Only OCR/automated
120				// extraction sets the flag in the first place.
121				if ('transaction_date' in safePatch) {
122					safePatch.suspicious_date = false;
123				}
124	
125				const { data, error } = await supabase
126					.from('receipts')
127					.update(safePatch)
128					.eq('id', id)
129					.select('*')
130					.single();
131				if (error) throw error;
132				return data as ReceiptRow;
133			});
134		}
135	
136		async createManual(
137			values: Required<Pick<ReceiptInsert, 'merchant_name' | 'total_amount' | 'transaction_date'>> &
138				Partial<ReceiptInsert>
139		) {
140			return withRetry(async () => {
141				// Manual receipts are intentional - user is explicitly entering the date
142				// Skip suspicious date validation to avoid false positives for old receipts
143				const valuesWithFlag: ReceiptInsert = {
144					...values,
145					suspicious_date: false
146				};
147	
148				const { data, error } = await supabase
149					.from('receipts')
150					.insert(valuesWithFlag)
151					.select('*')
152					.single();
153				if (error) throw error;
154				return data as ReceiptRow;
155			});
156		}
157	
158		validateFile(file: File): { ok: true } | { ok: false; message: string } {
159			const type = file.type;
160			const sizeMB = file.size / (1024 * 1024);
161			if ([...IMAGE_TYPES, PDF_TYPE].indexOf(type) === -1) {
162				return { ok: false, message: 'Unsupported file type. Allowed: JPEG, PNG, HEIC, PDF.' };
163			}
164			if (IMAGE_TYPES.includes(type) && sizeMB > MAX_IMAGE_MB) {
165				return { ok: false, message: `Image too large. Max ${MAX_IMAGE_MB}MB.` };
166			}
167			if (type === PDF_TYPE && sizeMB > MAX_PDF_MB) {
168				return { ok: false, message: `PDF too large. Max ${MAX_PDF_MB}MB.` };
169			}
170			return { ok: true };
171		}
172	
173		async uploadAndCreate(file: File) {
174			const val = this.validateFile(file);
175			if (!val.ok) throw new Error(val.message);
176	
177			return withRetry(async () => {
178				// #{#rsz2a} - Resize image before upload
179				let fileToUpload = file;
180				const shouldResize = ['image/jpeg', 'image/png'].includes(file.type);
181	
182				if (shouldResize) {
183					try {
184						const originalSize = file.size;
185						fileToUpload = await resizeImage(file, 2000, 0.85);
186						const resizedSize = fileToUpload.size;
187	
188						console.log(
189							`Image resized: ${(originalSize / 1024).toFixed(2)}KB → ${(resizedSize / 1024).toFixed(2)}KB (${((1 - resizedSize / originalSize) * 100).toFixed(1)}% reduction)`
190						);
191					} catch (error) {
192						console.error('Image resize failed, using original:', error);
193						fileToUpload = file; // Fall back to original
194					}
195				}
196	
197				const user = (await supabase.auth.getUser()).data.user;
198				if (!user) throw new Error('Not authenticated');
199				const folder = `${user.id}`;
200				const fileExt = fileToUpload.name.split('.').pop()?.toLowerCase() ?? 'bin';
201				const path = `${folder}/${crypto.randomUUID()}.${fileExt}`;
202				const { error: upErr } = await supabase.storage.from('receipts').upload(path, fileToUpload, {
203					contentType: fileToUpload.type,
204					upsert: false
205				});
206				if (upErr) throw upErr;
207	
208				// #{#sec2a} Generate short-lived signed URL for OCR processing
209				const signedUrl = await getSignedReceiptUrl(path, 300);
210	
211				// OCR - Call server-side API to process the file
212				const extract = signedUrl ? await this.extractOcrData(signedUrl, file.type) : null;
213	
214				// #{#rdc4b} #{#rdc5a} Correct OCR date from the verbatim raw string, then derive
215				// the suspicious_date flag (#{#dtv1b}) from the corrected value. Implausible,
216				// uncorrectable dates (wrong-token reads) are flagged rather than silently stored.
217				const { transaction_date: transactionDate, suspicious_date } = resolveOcrReceiptDate(
218					extract?.transaction_date ?? null,
219					extract?.raw_date_text,
220					new Date()
221				);
222				const currency = extract?.currency ?? null;
223	
224				// #{#fcr1a} #{#fcr2a} Fetch exchange rate at scan time for foreign currency receipts
225				let exchangeRate: number | null = null;
226				if (currency && currency !== 'CAD' && transactionDate) {
227					try {
228						const { ExchangeRateService } = await import('./ExchangeRateService');
229						exchangeRate = await ExchangeRateService.fetchRate(currency, transactionDate);
230					} catch {
231						// Rate fetch is best-effort — receipt is saved without rate
232					}
233				}
234	
235				const values: ReceiptInsert = {
236					receipt_image_path: path,
237					original_filename: sanitizeFilename(file.name), // #{#ofn2a} capture original name (pre-resize)
238					transaction_date: transactionDate,
239					total_amount: extract?.total_amount ?? null,
240					tax: extract?.tax ?? null,
241					merchant_name: extract?.merchant_name ?? null,
242					currency: currency,
243					exchange_rate_to_cad: exchangeRate,
244					credit_card_name: extract?.credit_card_name ?? null,
245					credit_card_last_4: extract?.credit_card_last_4 ?? null,
246					suspicious_date
247				};
248	
249				// #{#upr1a} #{#upr1b} If the insert fails, the storage upload above has already
250				// created a blob that no row will ever reference. Remove it before re-throwing so
251				// it doesn't become an orphan. Cleanup failure is logged but doesn't mask the
252				// original insert error — the caller sees what went wrong with the insert.
253				const { data, error } = await supabase.from('receipts').insert(values).select('*').single();
254				if (error) {
255					try {
256						const { error: removeErr } = await supabase.storage.from('receipts').remove([path]);
257						if (removeErr) {
258							console.error('orphan_storage_cleanup_failed', {
259								path,
260								insertError: error,
261								cleanupError: removeErr
262							});
263						}
264					} catch (cleanupError) {
265						console.error('orphan_storage_cleanup_failed', {
266							path,
267							insertError: error,
268							cleanupError
269						});
270					}
271					throw error;
272				}
273	
274				console.log('[ReceiptService] Receipt created:', {
275					id: data.id,
276					merchant_name: data.merchant_name,
277					family_id: data.family_id,
278					user_id: data.user_id,
279					transaction_date: data.transaction_date
280				});
281	
282				// #{#vca2a} - Auto-assign category based on vendor rules
283				const merchantName = extract?.merchant_name ?? null;
284				if (merchantName && data && data.family_id) {
285					try {
286						// Dynamic import to avoid circular dependency
287						const { ExpenseService } = await import('./ExpenseService');
288						const expenseService = new ExpenseService(supabase);
289	
290						// Check for matching vendor rule using family_id
291						const vendorRule = await expenseService.getVendorRule(data.family_id, merchantName);
292	
293						if (vendorRule) {
294							// Auto-assign category with source='auto'
295							await expenseService.assignCategory(data.id, vendorRule.category_id, 'auto');
296	
297							// #{#vca3b} - Log auto-assignment for debugging
298							console.log(
299								JSON.stringify({
300									event: 'vendor_rule_auto_assign',
301									timestamp: new Date().toISOString(),
302									family_id: data.family_id,
303									receipt_id: data.id,
304									merchant_name: merchantName,
305									category_id: vendorRule.category_id,
306									category_name: vendorRule.category_name,
307									source: 'auto',
308									context: 'upload'
309								})
310							);
311						}
312					} catch (autoAssignError) {
313						// #{#vca2a} - Graceful error handling: log but don't fail receipt creation
314						console.error(
315							'Auto-assignment failed, receipt created without category:',
316							autoAssignError
317						);
318					}
319				}
320	
321				return data as ReceiptRow;
322			});
323		}
324	
325		async delete(id: string, receiptImagePath?: string | null) {
326			return withRetry(async () => {
327				// determine storage path
328				let path = receiptImagePath ?? null;
329				if (!path) {
330					const { data, error } = await supabase
331						.from('receipts')
332						.select('receipt_image_path')
333						.eq('id', id)
334						.single();
335					if (error) throw error;
336					path = (data as { receipt_image_path: string | null } | null)?.receipt_image_path ?? null;
337				}
338	
339				// best-effort delete of storage object first to avoid orphan files
340				if (path) {
341					try {
342						await supabase.storage.from('receipts').remove([path]);
343					} catch {
344						// ignore storage deletion errors; proceed to delete DB row
345					}
346				}
347	
348				const { error: delErr } = await supabase.from('receipts').delete().eq('id', id);
349				if (delErr) throw delErr;
350				return { id };
351			});
352		}
353	
354		/**
355		 * #{#spl1a} Split a receipt into two partial receipts.
356		 *
357		 * Creates a new receipt with the specified split amount and reduces the
358		 * original receipt's amount accordingly. Both receipts share a split_group_id.
359		 *
360		 * @param receiptId The ID of the receipt to split
361		 * @param splitAmount The amount for the new split receipt
362		 * @returns The new receipt and the updated original
363		 */
364		async splitReceipt(
365			receiptId: string,
366			splitAmount: number,
367			splitDate?: string | null
368		): Promise<{ newReceipt: ReceiptRow; updatedOriginal: ReceiptRow }> {
369			// #{#spl2b} - Validate split amount (before any DB calls)
370			if (!Number.isFinite(splitAmount) || splitAmount <= 0) {
371				throw new Error('Split amount must be a positive finite number');
372			}
373			// Check at most 2 decimal places
374			if (Math.round(splitAmount * 100) !== splitAmount * 100) {
375				throw new Error('Split amount can have at most 2 decimal places');
376			}
377	
378			// #{#spl7c} - Validate split date if provided
379			if (splitDate !== undefined && splitDate !== null) {
380				if (splitDate === '' || !/^\d{4}-\d{2}-\d{2}$/.test(splitDate)) {
381					throw new Error('Please enter a valid date');
382				}
383				const parsed = new Date(splitDate);
384				if (isNaN(parsed.getTime())) {
385					throw new Error('Please enter a valid date');
386				}
387				// Verify the date components match (catches 2026-02-30 etc.)
388				const [year, month, day] = splitDate.split('-').map(Number);
389				if (
390					parsed.getUTCFullYear() !== year ||
391					parsed.getUTCMonth() !== month - 1 ||
392					parsed.getUTCDate() !== day
393				) {
394					throw new Error('Please enter a valid date');
395				}
396			}
397	
398			return withRetry(async () => {
399				// Auth check
400				const user = (await supabase.auth.getUser()).data.user;
401				if (!user) throw new Error('Not authenticated');
402	
403				// Fetch the original receipt
404				const { data: original, error: fetchError } = await supabase
405					.from('receipts')
406					.select('*')
407					.eq('id', receiptId)
408					.single();
409				if (fetchError) throw fetchError;
410				if (!original) throw new Error('Receipt not found');
411	
412				const originalAmount = (original as ReceiptRow).total_amount;
413				if (originalAmount == null || originalAmount <= 0) {
414					throw new Error('Cannot split a receipt with no amount');
415				}
416	
417				// Validate split amount against original total
418				const remainingAmount = Math.round((originalAmount - splitAmount) * 100) / 100;
419				if (splitAmount >= originalAmount || remainingAmount <= 0) {
420					throw new Error('Split amount must be less than the receipt total');
421				}
422	
423				// #{#spl1b} - Determine split_group_id
424				const splitGroupId = (original as any).split_group_id ?? crypto.randomUUID();
425	
426				// #{#spl7a} - Use splitDate if provided, otherwise inherit from original
427				const effectiveDate = splitDate ?? (original as ReceiptRow).transaction_date;
428	
429				// #{#spl7a} #{#spl7c} - Recalculate suspicious_date based on the split's own date
430				const effectiveSuspicious = splitDate
431					? isSuspiciousDate(splitDate)
432					: (original as ReceiptRow).suspicious_date;
433	
434				// #{#spl5a} - Insert new receipt first, then update original
435				const newReceiptData: ReceiptInsert = {
436					receipt_image_path: (original as ReceiptRow).receipt_image_path,
437					transaction_date: effectiveDate,
438					total_amount: splitAmount,
439					tax: null,
440					merchant_name: (original as ReceiptRow).merchant_name,
441					credit_card_name: (original as ReceiptRow).credit_card_name,
442					credit_card_last_4: (original as ReceiptRow).credit_card_last_4,
443					currency: (original as ReceiptRow).currency,
444					matched_transaction_id: null,
445					suspicious_date: effectiveSuspicious,
446					split_group_id: splitGroupId
447				};
448	
449				const { data: newReceipt, error: insertError } = await supabase
450					.from('receipts')
451					.insert(newReceiptData)
452					.select('*')
453					.single();
454				if (insertError) throw insertError;
455	
456				// Update original: reduce amount, set split_group_id, clear match
457				const { data: updatedOriginal, error: updateError } = await supabase
458					.from('receipts')
459					.update({
460						total_amount: remainingAmount,
461						matched_transaction_id: null,
462						split_group_id: splitGroupId
463					})
464					.eq('id', receiptId)
465					.select('*')
466					.single();
467	
468				if (updateError) {
469					// Rollback: delete the newly created receipt
470					try {
471						await supabase
472							.from('receipts')
473							.delete()
474							.eq('id', (newReceipt as ReceiptRow).id);
475					} catch {
476						// Best-effort rollback
477					}
478					throw updateError;
479				}
480	
481				return {
482					newReceipt: newReceipt as ReceiptRow,
483					updatedOriginal: updatedOriginal as ReceiptRow
484				};
485			});
486		}
487	
488		/**
489		 * #{#blk3a} Bulk delete multiple receipts in a single database operation
490		 * @param receiptIds Array of receipt IDs to delete
491		 * @returns Promise that resolves when deletion is complete
492		 */
493		async bulkDeleteReceipts(receiptIds: string[]): Promise<{ deletedCount: number }> {
494			return withRetry(async () => {
495				// Get authenticated user
496				const user = (await supabase.auth.getUser()).data.user;
497				if (!user) throw new Error('Not authenticated');
498	
499				// Delete all receipts in a single query using IN clause
500				// Only delete receipts belonging to the authenticated user
501				const { error } = await supabase
502					.from('receipts')
503					.delete()
504					.in('id', receiptIds)
505					.eq('user_id', user.id);
506	
507				if (error) throw error;
508	
509				// Return metadata about deletion
510				return { deletedCount: receiptIds.length };
511			});
512		}
513	}
