1	/**
2	 * Test Suite for Receipt Service - Date Validation Integration
3	 *
4	 * Tests for #{#dtv1b} - Database flag storage (suspicious_date column)
5	 *
6	 * Authority: developer
7	 * Priority: High
8	 *
9	 * Acceptance Criteria:
10	 * 1. Receipts table must have `suspicious_date` boolean column (default: false)
11	 * 2. Column must be set to `true` when date fails validation (#{#dtv1a})
12	 * 3. Flag must persist until user explicitly confirms or corrects the date
13	 * 4. Flag must be queryable for filtering suspicious receipts
14	 * 5. Manual date changes must NOT re-validate - always set flag to false
15	 * 6. Manual receipt creation must NOT validate dates - always set flag to false
16	 * 7. Email-scanned receipts must validate dates and set flag
17	 */
18	
19	import { describe, it, expect, beforeEach, vi, afterEach } from 'vitest';
20	import { ReceiptService } from './ReceiptService';
21	import type { ReceiptRow, ReceiptInsert } from '$lib/models/Receipt';
22	
23	// Mock Supabase client
24	vi.mock('$lib/supabaseClient', () => ({
25		supabase: {
26			auth: {
27				getUser: vi.fn().mockResolvedValue({
28					data: { user: { id: 'test-user-id' } }
29				})
30			},
31			from: vi.fn(),
32			storage: {
33				from: vi.fn()
34			}
35		}
36	}));
37	
38	// Mock date validation utility (will be imported by ReceiptService after implementation)
39	vi.mock('$lib/utils/dateValidation', () => ({
40		isSuspiciousDate: vi.fn()
41	}));
42	
43	// Mock signed URL utility (replaces getPublicUrl in ReceiptService)
44	vi.mock('$lib/utils/signedUrl', () => ({
45		getSignedReceiptUrl: vi.fn((path: string) =>
46			Promise.resolve(`https://example.com/receipts/${path}?token=signed`)
47		)
48	}));
49	
50	// Mock image resize so uploadAndCreate passes the original File through unchanged
51	vi.mock('$lib/utils/imageResize', () => ({
52		resizeImage: vi.fn((file: File) => Promise.resolve(file))
53	}));
54	
55	import { supabase } from '$lib/supabaseClient';
56	import { isSuspiciousDate } from '$lib/utils/dateValidation';
57	
58	describe('#{#dtv1b} - Suspicious Date Flag Storage', () => {
59		let mockFrom: any;
60		let mockSelect: any;
61		let mockInsert: any;
62		let mockUpdate: any;
63		let mockEq: any;
64		let mockSingle: any;
65		let mockOrder: any;
66	
67		beforeEach(() => {
68			vi.clearAllMocks();
69	
70			// Mock current date to 2025-12-09
71			vi.useFakeTimers();
72			vi.setSystemTime(new Date('2025-12-09T12:00:00Z'));
73	
74			// Setup Supabase mock chain
75			mockSingle = vi.fn();
76			mockEq = vi.fn().mockReturnValue({ select: vi.fn().mockReturnValue({ single: mockSingle }) });
77			mockOrder = vi.fn();
78			mockSelect = vi.fn().mockReturnValue({
79				single: mockSingle,
80				order: mockOrder
81			});
82			mockInsert = vi.fn().mockReturnValue({
83				select: mockSelect
84			});
85			mockUpdate = vi.fn().mockReturnValue({
86				eq: mockEq
87			});
88			mockFrom = vi.fn().mockReturnValue({
89				select: mockSelect,
90				insert: mockInsert,
91				update: mockUpdate,
92				delete: vi.fn(),
93				eq: mockEq,
94				in: vi.fn(),
95				order: mockOrder
96			});
97	
98			(supabase.from as any) = mockFrom;
99		});
100	
101		afterEach(() => {
102			vi.useRealTimers();
103		});
