1222		// and surface the resolved/rejected outcome as a Promise the test can assert on.
1223		async function runWithRetries<T>(file: File): Promise<RetryOutcome<T>> {
1224			const outcome: RetryOutcome<T> = {};
1225			const settled = ReceiptService.get()
1226				.uploadAndCreate(file)
1227				.then((v) => {
1228					outcome.value = v as T;
1229				})
1230				.catch((e: unknown) => {
1231					outcome.error = e instanceof Error ? e : new Error(String(e));
