508	/**
509	 * Test Suite for #{#upr2a} - Batch upload isolates per-file failures
510	 *
511	 * Specification: specs/specifications/upload-pipeline-resilience.md
512	 * Authority: developer
513	 *
514	 * Code already implements this in src/routes/receipts/+page.svelte (onFilesChanged).
515	 * These tests guard against regression. Two layers:
516	 *  (a) source-introspection — the .svelte file contains the right structural pattern
517	 *  (b) logic-level — a small helper mirrors the loop semantics and is unit-tested
518	 */
519	describe('#{#upr2a} Batch upload per-file isolation', () => {
520		const pagePath = join(process.cwd(), 'src/routes/receipts/+page.svelte');
521		const pageContent = readFileSync(pagePath, 'utf-8');
522	
523		describe('source-introspection — onFilesChanged structure', () => {
524			it('iterates files with a for-loop inside the handler', () => {
525				expect(pageContent).toMatch(/function onFilesChanged[\s\S]*?for\s*\([^)]*of\s+files\s*\)/);
526			});
527	
528			it('wraps each uploadAndCreate call in its own try/catch', () => {
529				expect(pageContent).toMatch(
530					/for\s*\([^)]*of\s+files\s*\)\s*\{[\s\S]*?try\s*\{[\s\S]*?uploadAndCreate[\s\S]*?\}\s*catch/
531				);
532			});
533	
534			it('accumulates per-file failures into a list', () => {
535				expect(pageContent).toMatch(/failures\s*:\s*string\[\]\s*=\s*\[\]/);
536				expect(pageContent).toMatch(/failures\.push/);
537			});
538	
539			it('prepends each successful receipt to allReceipts as it completes', () => {
540				// The success branch sets allReceipts = [receipt, ...allReceipts]
541				expect(pageContent).toMatch(/allReceipts\s*=\s*\[\s*receipt\s*,\s*\.\.\.allReceipts\s*\]/);
542			});
543	
544			it('builds a "Failed N of M" summary error when at least one upload failed', () => {
545				expect(pageContent).toMatch(/Failed \$\{failures\.length\} of \$\{files\.length\} receipt/);
546			});
547	
548			it('resets the file input value at the end so the same file can be re-uploaded', () => {
549				expect(pageContent).toMatch(/input\.value\s*=\s*['"][^'"]*['"]/);
550			});
551	
552			it('sets uploading=true before the loop and uploading=false after', () => {
553				// Both assignments live in onFilesChanged; failure here means the
554				// flag toggling has been removed/renamed.
555				expect(pageContent).toMatch(/uploading\s*=\s*true/);
556				expect(pageContent).toMatch(/uploading\s*=\s*false/);
557			});
558		});
559	
560		describe('logic-level — loop semantics', () => {
561			// Mirrors the onFilesChanged loop in pure JS so we can unit-test the contract
562			// without booting Svelte. If this passes but the page tests fail, the page has
563			// drifted away from the agreed contract.
564			async function uploadBatch<T>(
565				files: { name: string }[],
566				uploader: (file: { name: string }) => Promise<T>
567			) {
568				const successes: T[] = [];
569				const failures: string[] = [];
570				for (const file of files) {
571					try {
572						const r = await uploader(file);
573						successes.unshift(r); // prepended (matches +page.svelte behavior)
574					} catch (err) {
575						const message =
576							err && typeof err === 'object' && 'message' in err
577								? String((err as { message: unknown }).message)
578								: 'Failed to upload';
579						failures.push(`${file.name}: ${message}`);
580					}
581				}
582				const error =
583					failures.length > 0
584						? `Failed ${failures.length} of ${files.length} receipt(s):\n${failures.join('\n')}`
585						: null;
586				return { successes, failures, error };
587			}
588	
589			it('all N files succeed → all results captured, error stays null', async () => {
590				const files = [{ name: 'a.jpg' }, { name: 'b.jpg' }, { name: 'c.jpg' }];
591				const result = await uploadBatch(files, (f) => Promise.resolve({ id: f.name }));
592	
593				expect(result.successes).toHaveLength(3);
594				expect(result.error).toBeNull();
595				expect(result.failures).toHaveLength(0);
596			});
597	
598			it('file 2 of 3 throws → files 1 and 3 still succeed', async () => {
599				const files = [{ name: 'a.jpg' }, { name: 'bad.jpg' }, { name: 'c.jpg' }];
600				const result = await uploadBatch(files, (f) => {
601					if (f.name === 'bad.jpg') return Promise.reject(new Error('boom'));
602					return Promise.resolve({ id: f.name });
603				});
604	
605				expect(result.successes).toHaveLength(2);
606				expect(result.failures).toHaveLength(1);
607				expect(result.failures[0]).toBe('bad.jpg: boom');
608				expect(result.error).toContain('Failed 1 of 3 receipt(s)');
609				expect(result.error).toContain('bad.jpg: boom');
610			});
611	
612			it('all N files throw → no successes, error lists every failure', async () => {
613				const files = [{ name: 'a.jpg' }, { name: 'b.jpg' }];
614				const result = await uploadBatch(files, (f) => Promise.reject(new Error(`fail ${f.name}`)));
615	
616				expect(result.successes).toHaveLength(0);
617				expect(result.failures).toEqual(['a.jpg: fail a.jpg', 'b.jpg: fail b.jpg']);
618				expect(result.error).toContain('Failed 2 of 2 receipt(s)');
619			});
620	
621			it('error message defaults to "Failed to upload" when err.message is missing', async () => {
622				const files = [{ name: 'a.jpg' }];
623				const result = await uploadBatch(files, () => Promise.reject({}));
624				expect(result.failures[0]).toBe('a.jpg: Failed to upload');
625			});
626		});
627	});
