				fileToUpload = file; // Fall back to original
			}
		}

		const user = (await supabase.auth.getUser()).data.user;
		if (!user) throw new Error('Not authenticated');
		const folder = `${user.id}`;
		const fileExt = fileToUpload.name.split('.').pop()?.toLowerCase() ?? 'bin';
		const path = `${folder}/${crypto.randomUUID()}.${fileExt}`;
		const { error: upErr } = await supabase.storage.from('receipts').upload(path, fileToUpload, {
