/**
 * Upload a receipt file, extract its data via OCR, and persist the receipt row.
 *
 * Resilience invariants (see upload-pipeline-resilience spec):
 * - OCR is best-effort: any OCR failure still creates the receipt without extracted data.
 * - No orphan storage files: if the insert fails after upload, the blob is removed.
 */
async uploadAndCreate(file: File) {
	const val = this.validateFile(file);
	if (!val.ok) throw new Error(val.message);

	return withRetry(async () => {
		const fileToUpload = await this.prepareFileForUpload(file);
		const path = await this.uploadToStorage(fileToUpload);
		const extract = await this.extractReceiptDataFailSoft(path, file.type);
		const values = await this.buildReceiptInsert(file, path, extract);
		const data = await this.insertReceiptOrCleanupUpload(values, path);
		await this.autoAssignCategoryBestEffort(data, extract?.merchant_name ?? null);
		return data as ReceiptRow;
	});
}

/** #{#rsz2a} Resize JPEG/PNG images before upload; falls back to the original on failure. */
private async prepareFileForUpload(file: File): Promise<File> {
	const shouldResize = ['image/jpeg', 'image/png'].includes(file.type);
	if (!shouldResize) return file;

	try {
		const originalSize = file.size;
		const resized = await resizeImage(file, 2000, 0.85);
		const resizedSize = resized.size;

		console.log(
			`Image resized: ${(originalSize / 1024).toFixed(2)}KB → ${(resizedSize / 1024).toFixed(2)}KB (${((1 - resizedSize / originalSize) * 100).toFixed(1)}% reduction)`
		);
		return resized;
	} catch (error) {
		console.error('Image resize failed, using original:', error);
		return file; // Fall back to original
	}
}

/** Upload the file under the user's folder and return its storage path. Throws on failure. */
private async uploadToStorage(fileToUpload: File): Promise<string> {
	const user = (await supabase.auth.getUser()).data.user;
	if (!user) throw new Error('Not authenticated');
	const folder = `${user.id}`;
	const fileExt = fileToUpload.name.split('.').pop()?.toLowerCase() ?? 'bin';
	const path = `${folder}/${crypto.randomUUID()}.${fileExt}`;
	const { error: upErr } = await supabase.storage.from('receipts').upload(path, fileToUpload, {
		contentType: fileToUpload.type,
		upsert: false
	});
	if (upErr) throw upErr;
	return path;
}

/**
 * #{#sec2a} OCR via a short-lived signed URL. Best-effort: returns null when the signed
 * URL cannot be generated or the OCR API fails, so the upload pipeline survives outages.
 */
private async extractReceiptDataFailSoft(
	path: string,
	mimeType: string
): Promise<ReceiptExtract | null> {
	const signedUrl = await getSignedReceiptUrl(path, 300);
	return signedUrl ? await this.extractOcrData(signedUrl, mimeType) : null;
}

/** #{#fcr1a} #{#fcr2a} Fetch exchange rate at scan time for foreign currency receipts. */
private async fetchExchangeRateBestEffort(
	currency: string | null,
	transactionDate: string | null
): Promise<number | null> {
	if (!currency || currency === 'CAD' || !transactionDate) return null;
	try {
		const { ExchangeRateService } = await import('./ExchangeRateService');
		return await ExchangeRateService.fetchRate(currency, transactionDate);
	} catch {
		// Rate fetch is best-effort — receipt is saved without rate
		return null;
	}
}

/** Map the (possibly null) OCR extract onto the row to insert. */
private async buildReceiptInsert(
	file: File,
	path: string,
	extract: ReceiptExtract | null
): Promise<ReceiptInsert> {
	// #{#rdc4b} #{#rdc5a} Correct OCR date from the verbatim raw string, then derive
	// the suspicious_date flag (#{#dtv1b}) from the corrected value. Implausible,
	// uncorrectable dates (wrong-token reads) are flagged rather than silently stored.
	const { transaction_date: transactionDate, suspicious_date } = resolveOcrReceiptDate(
		extract?.transaction_date ?? null,
		extract?.raw_date_text,
		new Date()
	);
	const currency = extract?.currency ?? null;
	const exchangeRate = await this.fetchExchangeRateBestEffort(currency, transactionDate);

	return {
		receipt_image_path: path,
		original_filename: sanitizeFilename(file.name), // #{#ofn2a} capture original name (pre-resize)
		transaction_date: transactionDate,
		total_amount: extract?.total_amount ?? null,
		tax: extract?.tax ?? null,
		merchant_name: extract?.merchant_name ?? null,
		currency: currency,
		exchange_rate_to_cad: exchangeRate,
		credit_card_name: extract?.credit_card_name ?? null,
		credit_card_last_4: extract?.credit_card_last_4 ?? null,
		suspicious_date
	};
}

/**
 * #{#upr1a} #{#upr1b} Insert the receipt row. If the insert fails, the storage upload has
 * already created a blob that no row will ever reference — remove it before re-throwing so
 * it doesn't become an orphan. Cleanup failure is logged but doesn't mask the original
 * insert error — the caller sees what went wrong with the insert.
 */
private async insertReceiptOrCleanupUpload(
	values: ReceiptInsert,
	path: string
): Promise<InsertedReceiptRow> {
	const { data, error } = await supabase.from('receipts').insert(values).select('*').single();
	if (error) {
		await this.removeUploadedFileBestEffort(path, error);
		throw error;
	}

	const row = data as InsertedReceiptRow;
	console.log('[ReceiptService] Receipt created:', {
		id: row.id,
		merchant_name: row.merchant_name,
		family_id: row.family_id,
		user_id: row.user_id,
		transaction_date: row.transaction_date
	});
	return row;
}

/** Remove the just-uploaded blob; log (never throw) so the insert error stays visible. */
private async removeUploadedFileBestEffort(path: string, insertError: unknown): Promise<void> {
	try {
		const { error: removeErr } = await supabase.storage.from('receipts').remove([path]);
		if (removeErr) {
			console.error('orphan_storage_cleanup_failed', {
				path,
				insertError,
				cleanupError: removeErr
			});
		}
	} catch (cleanupError) {
		console.error('orphan_storage_cleanup_failed', {
			path,
			insertError,
			cleanupError
		});
	}
}

/**
 * #{#vca2a} Auto-assign a category based on vendor rules. Graceful error handling:
 * failures are logged but never fail receipt creation.
 */
private async autoAssignCategoryBestEffort(
	receipt: InsertedReceiptRow | null,
	merchantName: string | null
): Promise<void> {
	if (!merchantName || !receipt || !receipt.family_id) return;

	try {
		// Dynamic import to avoid circular dependency
		const { ExpenseService } = await import('./ExpenseService');
		const expenseService = new ExpenseService(supabase);

		// Check for matching vendor rule using family_id
		const vendorRule = await expenseService.getVendorRule(receipt.family_id, merchantName);
		if (!vendorRule) return;

		// Auto-assign category with source='auto'
		await expenseService.assignCategory(receipt.id, vendorRule.category_id, 'auto');

		// #{#vca3b} - Log auto-assignment for debugging
		console.log(
			JSON.stringify({
				event: 'vendor_rule_auto_assign',
				timestamp: new Date().toISOString(),
				family_id: receipt.family_id,
				receipt_id: receipt.id,
				merchant_name: merchantName,
				category_id: vendorRule.category_id,
				category_name: vendorRule.category_name,
				source: 'auto',
				context: 'upload'
			})
		);
	} catch (autoAssignError) {
		// #{#vca2a} - Graceful error handling: log but don't fail receipt creation
		console.error('Auto-assignment failed, receipt created without category:', autoAssignError);
	}
}

