async splitReceipt(
	receiptId: string,
	splitAmount: number,
	splitDate?: string | null
): Promise<{ newReceipt: ReceiptRow; updatedOriginal: ReceiptRow }> {
	// #{#spl2b} - Validate split amount (before any DB calls)
	if (!Number.isFinite(splitAmount) || splitAmount <= 0) {
		throw new Error('Split amount must be a positive finite number');
	}
	// Check at most 2 decimal places
	if (Math.round(splitAmount * 100) !== splitAmount * 100) {
		throw new Error('Split amount can have at most 2 decimal places');
	}

	// #{#spl7c} - Validate split date if provided
	if (splitDate !== undefined && splitDate !== null) {
		if (splitDate === '' || !/^\d{4}-\d{2}-\d{2}$/.test(splitDate)) {
			throw new Error('Please enter a valid date');
		}
		const parsed = new Date(splitDate);
		if (isNaN(parsed.getTime())) {
			throw new Error('Please enter a valid date');
		}
		// Verify the date components match (catches 2026-02-30 etc.)
		const [year, month, day] = splitDate.split('-').map(Number);
		if (
			parsed.getUTCFullYear() !== year ||
			parsed.getUTCMonth() !== month - 1 ||
			parsed.getUTCDate() !== day
		) {
			throw new Error('Please enter a valid date');
		}
	}

	return withRetry(async () => {
		// Auth check
		const user = (await supabase.auth.getUser()).data.user;
		if (!user) throw new Error('Not authenticated');

		// Fetch the original receipt
		const { data: original, error: fetchError } = await supabase
			.from('receipts')
			.select('*')
			.eq('id', receiptId)
			.single();
		if (fetchError) throw fetchError;
		if (!original) throw new Error('Receipt not found');

		const originalAmount = (original as ReceiptRow).total_amount;
		if (originalAmount == null || originalAmount <= 0) {
			throw new Error('Cannot split a receipt with no amount');
		}

		// Validate split amount against original total
		const remainingAmount = Math.round((originalAmount - splitAmount) * 100) / 100;
		if (splitAmount >= originalAmount || remainingAmount <= 0) {
			throw new Error('Split amount must be less than the receipt total');
		}

		// #{#spl1b} - Determine split_group_id
		const splitGroupId = (original as any).split_group_id ?? crypto.randomUUID();

		// #{#spl7a} - Use splitDate if provided, otherwise inherit from original
		const effectiveDate = splitDate ?? (original as ReceiptRow).transaction_date;

		// #{#spl7a} #{#spl7c} - Recalculate suspicious_date based on the split's own date
		const effectiveSuspicious = splitDate
			? isSuspiciousDate(splitDate)
			: (original as ReceiptRow).suspicious_date;

		// #{#spl5a} - Insert new receipt first, then update original
		const newReceiptData: ReceiptInsert = {
			receipt_image_path: (original as ReceiptRow).receipt_image_path,
			transaction_date: effectiveDate,
			total_amount: splitAmount,
			tax: null,
			merchant_name: (original as ReceiptRow).merchant_name,
			credit_card_name: (original as ReceiptRow).credit_card_name,
			credit_card_last_4: (original as ReceiptRow).credit_card_last_4,
			currency: (original as ReceiptRow).currency,
			matched_transaction_id: null,
			suspicious_date: effectiveSuspicious,
			split_group_id: splitGroupId
		};

		const { data: newReceipt, error: insertError } = await supabase
			.from('receipts')
			.insert(newReceiptData)
			.select('*')
			.single();
		if (insertError) throw insertError;

		// Update original: reduce amount, set split_group_id, clear match
		const { data: updatedOriginal, error: updateError } = await supabase
			.from('receipts')
			.update({
				total_amount: remainingAmount,
				matched_transaction_id: null,
				split_group_id: splitGroupId
			})
			.eq('id', receiptId)
			.select('*')
			.single();

		if (updateError) {
			// Rollback: delete the newly created receipt
			try {
				await supabase
					.from('receipts')
					.delete()
					.eq('id', (newReceipt as ReceiptRow).id);
			} catch {
				// Best-effort rollback
			}
			throw updateError;
		}

		return {
			newReceipt: newReceipt as ReceiptRow,
			updatedOriginal: updatedOriginal as ReceiptRow
		};
	});
}

