async splitReceipt(
	receiptId: string,
	splitAmount: number,
	splitDate?: string | null
): Promise<{ newReceipt: ReceiptRow; updatedOriginal: ReceiptRow }> {
	// Validate inputs before any DB calls
	ReceiptService.validateSplitAmount(splitAmount);
	ReceiptService.validateSplitDate(splitDate);

	return withRetry(async () => {
		// Auth check
		const user = (await supabase.auth.getUser()).data.user;
		if (!user) throw new Error('Not authenticated');

		const original = await this.fetchOriginalForSplit(receiptId);
		const remainingAmount = ReceiptService.computeRemainingAmount(
			original.total_amount,
			splitAmount
		);

		// #{#spl1b} - Determine split_group_id
		const splitGroupId = original.split_group_id ?? crypto.randomUUID();

		// #{#spl5a} - Insert new receipt first, then update original
		const newReceipt = await this.insertSplitReceipt(
			ReceiptService.buildSplitReceiptInsert(original, splitAmount, splitDate, splitGroupId)
		);
		const updatedOriginal = await this.reduceOriginalAfterSplitOrRollback(
			receiptId,
			remainingAmount,
			splitGroupId,
			newReceipt.id
		);

		return { newReceipt, updatedOriginal };
	});
}

/** #{#spl2b} Reject non-finite, non-positive, or sub-cent split amounts. */
private static validateSplitAmount(splitAmount: number): void {
	if (!Number.isFinite(splitAmount) || splitAmount <= 0) {
		throw new Error('Split amount must be a positive finite number');
	}
	// Check at most 2 decimal places
	if (Math.round(splitAmount * 100) !== splitAmount * 100) {
		throw new Error('Split amount can have at most 2 decimal places');
	}
}

/** #{#spl7c} Reject malformed or impossible (e.g. 2026-02-30) split dates when provided. */
private static validateSplitDate(splitDate?: string | null): void {
	if (splitDate === undefined || splitDate === null) return;

	if (splitDate === '' || !/^\d{4}-\d{2}-\d{2}$/.test(splitDate)) {
		throw new Error('Please enter a valid date');
	}
	const parsed = new Date(splitDate);
	if (isNaN(parsed.getTime())) {
		throw new Error('Please enter a valid date');
	}
	// Verify the date components match (catches 2026-02-30 etc.)
	const [year, month, day] = splitDate.split('-').map(Number);
	if (
		parsed.getUTCFullYear() !== year ||
		parsed.getUTCMonth() !== month - 1 ||
		parsed.getUTCDate() !== day
	) {
		throw new Error('Please enter a valid date');
	}
}

private async fetchOriginalForSplit(receiptId: string): Promise<ReceiptRow> {
	const { data: original, error: fetchError } = await supabase
		.from('receipts')
