		.eq('id', receiptId)
		.single();
	if (fetchError) throw fetchError;
	if (!original) throw new Error('Receipt not found');
	return original as ReceiptRow;
}

/** Validate the split against the original total and return what remains on the original. */
private static computeRemainingAmount(
	originalAmount: number | null,
	splitAmount: number
): number {
	if (originalAmount == null || originalAmount <= 0) {
		throw new Error('Cannot split a receipt with no amount');
	}
	const remainingAmount = Math.round((originalAmount - splitAmount) * 100) / 100;
	if (splitAmount >= originalAmount || remainingAmount <= 0) {
		throw new Error('Split amount must be less than the receipt total');
	}
	return remainingAmount;
}

/** The new split inherits the original's identity fields but never its transaction match. */
private static buildSplitReceiptInsert(
	original: ReceiptRow,
	splitAmount: number,
	splitDate: string | null | undefined,
	splitGroupId: string
): ReceiptInsert {
	// #{#spl7a} - Use splitDate if provided, otherwise inherit from original
	const effectiveDate = splitDate ?? original.transaction_date;

	// #{#spl7a} #{#spl7c} - Recalculate suspicious_date based on the split's own date
	const effectiveSuspicious = splitDate ? isSuspiciousDate(splitDate) : original.suspicious_date;

	return {
		receipt_image_path: original.receipt_image_path,
		transaction_date: effectiveDate,
		total_amount: splitAmount,
		tax: null,
		merchant_name: original.merchant_name,
		credit_card_name: original.credit_card_name,
		credit_card_last_4: original.credit_card_last_4,
		currency: original.currency,
		matched_transaction_id: null,
		suspicious_date: effectiveSuspicious,
		split_group_id: splitGroupId
	};
}

private async insertSplitReceipt(newReceiptData: ReceiptInsert): Promise<ReceiptRow> {
	const { data: newReceipt, error: insertError } = await supabase
		.from('receipts')
		.insert(newReceiptData)
		.select('*')
		.single();
	if (insertError) throw insertError;
	return newReceipt as ReceiptRow;
}

/**
 * #{#spl5a} Update the original (reduce amount, set split_group_id, clear match).
 * On failure, best-effort delete of the just-inserted split keeps the pair consistent.
 */
private async reduceOriginalAfterSplitOrRollback(
	receiptId: string,
	remainingAmount: number,
	splitGroupId: string,
	newReceiptId: string
): Promise<ReceiptRow> {
	const { data: updatedOriginal, error: updateError } = await supabase
		.from('receipts')
		.update({
			total_amount: remainingAmount,
			matched_transaction_id: null,
			split_group_id: splitGroupId
		})
		.eq('id', receiptId)
		.select('*')
		.single();

	if (updateError) {
		// Rollback: delete the newly created receipt
		try {
			await supabase.from('receipts').delete().eq('id', newReceiptId);
		} catch {
			// Best-effort rollback
		}
		throw updateError;
	}

	return updatedOriginal as ReceiptRow;
}

